import { cookies, headers } from 'next/headers'

// Picks the highest-weighted language tag, e.g. "fr-CH, fr;q=0.9, en;q=0.8" -> "fr-CH"
function getPreferredLanguage(acceptLanguage: string | null): string | null {
  if (!acceptLanguage) return null

  const languages = acceptLanguage
    .split(',')
    .map((part) => {
      const [tag, ...params] = part.trim().split(';')
      const qParam = params.find((p) => p.trim().startsWith('q='))
      const q = qParam ? Number.parseFloat(qParam.trim().slice(2)) : 1
      return { tag: tag.trim(), q: Number.isNaN(q) ? 0 : q }
    })
    .filter(({ tag, q }) => tag && tag !== '*' && q > 0)
    .sort((a, b) => b.q - a.q)

  return languages[0]?.tag ?? null
}

export default async function Home() {
  const cookieStore = await cookies()
  const headersList = await headers()

  const theme = cookieStore.get('theme')?.value || 'light'
  const language =
    getPreferredLanguage(headersList.get('accept-language')) ?? 'Not specified'

  return (
    <main>
      <h1>User Preferences</h1>
      <p>
        Theme: <strong>{theme}</strong>
      </p>
      <p>
        Preferred language: <strong>{language}</strong>
      </p>
    </main>
  )
}

